"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[863],{5581:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Monitoramento da Pol\xedtica Urbana","href":"/monitoramento/en/","docId":"intro","unlisted":false},{"type":"category","label":"Dimens\xf5es de Monitoramento","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Compacidade e policentrismo","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Do que se trata?","href":"/monitoramento/en/dimensoes/compacidade_e_policentrismo/conceito","docId":"dimensoes/compacidade_e_policentrismo/conceito","unlisted":false},{"type":"link","label":"O que pretende responder?","href":"/monitoramento/en/dimensoes/compacidade_e_policentrismo/questoes","docId":"dimensoes/compacidade_e_policentrismo/questoes","unlisted":false},{"type":"link","label":"Publica\xe7\xf5es","href":"/monitoramento/en/dimensoes/compacidade_e_policentrismo/publicacoes","docId":"dimensoes/compacidade_e_policentrismo/publicacoes","unlisted":false}],"href":"/monitoramento/en/category/compacidade-e-policentrismo"},{"type":"link","label":"Espa\xe7o p\xfablico seguro, inclusivo, acess\xedvel e verde","href":"/monitoramento/en/dimensoes/espa\xe7o_publico","docId":"dimensoes/espa\xe7o_publico","unlisted":false},{"type":"link","label":"Tecnologia resiliente","href":"/monitoramento/en/dimensoes/tecnologia_resiliente","docId":"dimensoes/tecnologia_resiliente","unlisted":false},{"type":"link","label":"Urbaniza\xe7\xe3o inclusiva","href":"/monitoramento/en/dimensoes/urbanizacao_inclusiva","docId":"dimensoes/urbanizacao_inclusiva","unlisted":false},{"type":"link","label":"Vazios e expans\xf5es urbanas planejadas","href":"/monitoramento/en/dimensoes/vazios_e_expansoes","docId":"dimensoes/vazios_e_expansoes","unlisted":false},{"type":"link","label":"Habita\xe7\xe3o sustent\xe1vel, adequada, segura e economicamente acess\xedvel","href":"/monitoramento/en/dimensoes/habitacao_sustentavel","docId":"dimensoes/habitacao_sustentavel","unlisted":false},{"type":"link","label":"Gest\xe3o sustent\xe1vel dos recursos naturais","href":"/monitoramento/en/dimensoes/gestao_sustentavel","docId":"dimensoes/gestao_sustentavel","unlisted":false},{"type":"link","label":"Gest\xe3o compartilhada","href":"/monitoramento/en/dimensoes/gestao_compartilhada","docId":"dimensoes/gestao_compartilhada","unlisted":false},{"type":"link","label":"Assentamentos prec\xe1rios","href":"/monitoramento/en/dimensoes/assentamentos_precarios","docId":"dimensoes/assentamentos_precarios","unlisted":false},{"type":"link","label":"Patrim\xf4nio cultural","href":"/monitoramento/en/dimensoes/patrimonio_cultural","docId":"dimensoes/patrimonio_cultural","unlisted":false},{"type":"link","label":"Transporte sustent\xe1vel e eficiente","href":"/monitoramento/en/dimensoes/transporte_sustentavel","docId":"dimensoes/transporte_sustentavel","unlisted":false}],"href":"/monitoramento/en/category/dimens\xf5es-de-monitoramento"},{"type":"category","label":"Instrumentos urban\xedsticos","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Outorga Onerosa do Direito de Construir (OODC)","href":"/monitoramento/en/instrumentos/oodc","docId":"instrumentos/oodc","unlisted":false},{"type":"link","label":"Transfere\u0302ncia do Direito de Construir (TDC)","href":"/monitoramento/en/instrumentos/tdc","docId":"instrumentos/tdc","unlisted":false},{"type":"category","label":"Opera\xe7\xf5es Urbanas","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Opera\xe7\xf5es Urbanas Consorciadas (OUC)","href":"/monitoramento/en/instrumentos/operacoes_urbanas/ouc","docId":"instrumentos/operacoes_urbanas/ouc","unlisted":false},{"type":"link","label":"Opera\xe7\xf5es Urbanas Simplificadas (OUS)","href":"/monitoramento/en/instrumentos/operacoes_urbanas/ous","docId":"instrumentos/operacoes_urbanas/ous","unlisted":false}],"href":"/monitoramento/en/category/opera\xe7\xf5es-urbanas"}],"href":"/monitoramento/en/category/instrumentos-urban\xedsticos"},{"type":"category","label":"Metodologia","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Introdu\xe7\xe3o","href":"/monitoramento/en/metodologia/introducao","docId":"metodologia/introducao","unlisted":false},{"type":"link","label":"Informa\xe7\xf5es importantes","href":"/monitoramento/en/metodologia/informacoes","docId":"metodologia/informacoes","unlisted":false}],"href":"/monitoramento/en/category/metodologia"}]},"docs":{"dimensoes/assentamentos_precarios":{"id":"dimensoes/assentamentos_precarios","title":"Assentamentos prec\xe1rios","description":"Aborda o monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol do planejamento dos assentamentos de interesse social, incluindo os Planos Globais Espec\xedficos (PGE), Planos de Regularizac\u0327a\u0303o Urbani\u0301stica (PRU) para \xc1reas de Interesse Social (AEIS) ocupadas e diretrizes de preserva\xe7\xe3o ambiental e de ocupac\u0327a\u0303o especial de interesse social para a\u0301reas especiais de interesse ambiental desocupadas e dotadas de atributos ambientais relevantes.","sidebar":"tutorialSidebar"},"dimensoes/compacidade_e_policentrismo/conceito":{"id":"dimensoes/compacidade_e_policentrismo/conceito","title":"Do que se trata?","description":"A Dimens\xe3o Compacidade e Policentrismo abarca as quest\xf5es de monitoramento que tratam do direcionamento da pol\xedtica urbana visando o fortalecimento das centralidades em diferentes \xe1reas da cidade - policentrismo - dotadas de densidades urbanas resid\xeancias, de atividades econ\xf4micas e oportunidades de emprego, a partir da diversidades de usos - compacidade - com equil\xedbrio sustent\xe1vel na utiliza\xe7\xe3o dos recursos naturais e do solo.","sidebar":"tutorialSidebar"},"dimensoes/compacidade_e_policentrismo/publicacoes":{"id":"dimensoes/compacidade_e_policentrismo/publicacoes","title":"Publica\xe7\xf5es","description":"Os pain\xe9is s\xe3o divididos em fun\xe7\xe3o de sua finalidade","sidebar":"tutorialSidebar"},"dimensoes/compacidade_e_policentrismo/questoes":{"id":"dimensoes/compacidade_e_policentrismo/questoes","title":"O que pretende responder?","description":"A capacidade de suporte construtiva e populacional est\xe1 sendo orientada nas diferentes unidades territoriais? As centralidades da cidade seguem o conceito de compacidade? As centralidades da cidade seguem o conceito de policentrismo?","sidebar":"tutorialSidebar"},"dimensoes/espa\xe7o_publico":{"id":"dimensoes/espa\xe7o_publico","title":"Espa\xe7o p\xfablico seguro, inclusivo, acess\xedvel e verde","description":"Monitora a orienta\xe7\xe3o da pol\xedtica urbana em prol da qualifica\xe7\xe3o do espa\xe7o p\xfablico por meio dos instrumentos das gentilezas urbanas e da arrecada\xe7\xe3o da Outorga do Direito de Construir para o fundo das Centralidades.","sidebar":"tutorialSidebar"},"dimensoes/gestao_compartilhada":{"id":"dimensoes/gestao_compartilhada","title":"Gest\xe3o compartilhada","description":"Trata do monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol do engajamento da sociedade civil e da flexibilidade no desenvolvimento de planos a partir de avalia\xe7\xf5es sistem\xe1ticas, por meio da realiza\xe7\xe3o quadrienal da Confer\xeancia Municipal de Pol\xedtica Urbana, do F\xf3rum das \xc1reas de Diretrizes Especiais- FADES e do monitoramento do cumprimento e da efic\xe1cia da legisla\xe7\xe3o urban\xedstica no \xe2mbito do COMPUR.","sidebar":"tutorialSidebar"},"dimensoes/gestao_sustentavel":{"id":"dimensoes/gestao_sustentavel","title":"Gest\xe3o sustent\xe1vel dos recursos naturais","description":"Trata do monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol das redes de estrutura\xe7\xe3o ambiental, incluindo as conex\xf5es de fundo de vale e conex\xf5es verdes.","sidebar":"tutorialSidebar"},"dimensoes/habitacao_sustentavel":{"id":"dimensoes/habitacao_sustentavel","title":"Habita\xe7\xe3o sustent\xe1vel, adequada, segura e economicamente acess\xedvel","description":"Trata do monitoramento da orienta\xe7\xe3o da pol\xedtica urbana por meio da destina\xe7\xe3o dos recursos da ODC ao Fundo Municipal de Habitac\u0327a\u0303o Popular - FMHP,  do incentivo a produc\u0327a\u0303o de Habitac\u0327a\u0303o de Interesse Social - HIS - nas a\u0301reas centrais e nas centralidades, dos instrumentos de poli\u0301tica urbana para subsidiar a produc\u0327a\u0303o de unidades habitacionais de interesse social e por fim, da conversa\u0303o de edificac\u0327o\u0303es existentes na a\u0301rea central para o uso residencial ou em outras regio\u0303es.","sidebar":"tutorialSidebar"},"dimensoes/patrimonio_cultural":{"id":"dimensoes/patrimonio_cultural","title":"Patrim\xf4nio cultural","description":"Aborda o monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol da valorizac\u0327a\u0303o do patrimo\u0302nio cultural, comunidades locais na promoc\u0327a\u0303o e disseminac\u0327a\u0303o de conhecimento do patrimo\u0302nio cultural material e imaterial por meio da aplicac\u0327a\u0303o da Transfere\u0302ncia do Direito de Construir - TDC.","sidebar":"tutorialSidebar"},"dimensoes/tecnologia_resiliente":{"id":"dimensoes/tecnologia_resiliente","title":"Tecnologia resiliente","description":"Aborda o monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol de instrumentos de promo\xe7\xe3o da resili\xeancia urbana como \xe1rea perme\xe1vel em terreno manual nos lotes, instalac\u0327a\u0303o de caixa de captac\u0327a\u0303o nas edificac\u0327o\u0303es; tipologias arquiteto\u0302nicas especi\u0301ficas para a\u0301reas sujeitas a inundac\u0327o\u0303es, contenc\u0327a\u0303o do adensamento nas a\u0301reas de fundo de vale por meio do desenvolvimento de planos de ocupac\u0327a\u0303o especi\u0301ficos, a\u0301rea adicional de uso comum para edificac\u0327o\u0303es residenciais que adotarem tecnologias de resilie\u0302ncia e sustentabilidade e gentileza urbana para melhoria do espac\u0327o pu\u0301blico, vinculadas a\u0300 possibilidade de acre\u0301scimo de a\u0301rea a\u0300s edificac\u0327o\u0303es sem o\u0302nus moneta\u0301rio.","sidebar":"tutorialSidebar"},"dimensoes/transporte_sustentavel":{"id":"dimensoes/transporte_sustentavel","title":"Transporte sustent\xe1vel e eficiente","description":"Aborda o monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol da qualifica\xe7\xe3o do transporte sustent\xe1vel e eficiente e da conectividade entre a pol\xedtica urbana e as diretrizes da mobilidade urbana por meio do incentivo aos modos n\xe3o motorizados de transporte, do desenvolvimento orientado ao transporte sustent\xe1vel, da qualifica\xe7\xe3o dos meios de transporte coletivos, da garantia a acessibilidade universal ao sistema de mobilidade e da integra\xe7\xe3o de todos os modais de transporte.","sidebar":"tutorialSidebar"},"dimensoes/urbanizacao_inclusiva":{"id":"dimensoes/urbanizacao_inclusiva","title":"Urbaniza\xe7\xe3o inclusiva","description":"Aborda o monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol da captura e o compartilhamento do incremento no valor da terra e da propriedade por meio da aplica\xe7\xe3o da Outorga Onerosa do direito de Construir (ODC) e do desenvolvimento de Opera\xe7\xf5es Urbanas.","sidebar":"tutorialSidebar"},"dimensoes/vazios_e_expansoes":{"id":"dimensoes/vazios_e_expansoes","title":"Vazios e expans\xf5es urbanas planejadas","description":"Trata do monitoramento da orienta\xe7\xe3o da pol\xedtica urbana em prol da preven\xe7\xe3o e desest\xedmulo \xe0 produ\xe7\xe3o de vazios urbanos por meio dos instrumentos do Parcelamento da Edifica\xe7\xe3o e da Utiliza\xe7\xe3o Compuls\xf3rios (PEUC) e do Imposto Predial e Territorial Urbano (IPTU) progressivo no tempo.","sidebar":"tutorialSidebar"},"instrumentos/oodc":{"id":"instrumentos/oodc","title":"Outorga Onerosa do Direito de Construir (OODC)","description":"A Outorga Onerosa do Direito de Construir (OODC) \xe9 um instrumento jur\xeddico que permite a constru\xe7\xe3o acima do coeficiente b\xe1sico de aproveitamento do solo. O propriet\xe1rio do im\xf3vel paga uma contrapartida financeira ao munic\xedpio para isso.","sidebar":"tutorialSidebar"},"instrumentos/operacoes_urbanas/ouc":{"id":"instrumentos/operacoes_urbanas/ouc","title":"Opera\xe7\xf5es Urbanas Consorciadas (OUC)","description":"As Opera\xe7\xf5es Urbanas Consorciadas t\xeam por objetivo promover altera\xe7\xf5es estruturais, melhorias sociais e valoriza\xe7\xe3o ambiental em \xe1reas estrat\xe9gicas da cidade. A implementa\xe7\xe3o deste instrumento ocorre sob a coordena\xe7\xe3o do Poder Executivo Municipal, com a participa\xe7\xe3o dos propriet\xe1rios de im\xf3veis, moradores, usu\xe1rios permanentes e investidores privados.","sidebar":"tutorialSidebar"},"instrumentos/operacoes_urbanas/ous":{"id":"instrumentos/operacoes_urbanas/ous","title":"Opera\xe7\xf5es Urbanas Simplificadas (OUS)","description":"A Opera\xe7\xe3o Urbana Simplificada, sempre motivada por interesse p\xfablico, destina-se a viabilizar interven\xe7\xf5es tais como: tratamento urban\xedstico de \xe1reas p\xfablicas; abertura de vias ou melhorias no sistema vi\xe1rio; implanta\xe7\xe3o de programa habitacional de interesse social; implanta\xe7\xe3o de equipamentos p\xfablicos; recupera\xe7\xe3o do patrim\xf4nio cultural; prote\xe7\xe3o ambiental; reurbaniza\xe7\xe3o; ameniza\xe7\xe3o dos efeitos negativos das ilhas de calor sobre a qualidade de vida; regulariza\xe7\xe3o de edifica\xe7\xf5es e de usos; requalifica\xe7\xe3o de \xe1reas p\xfablicas.","sidebar":"tutorialSidebar"},"instrumentos/tdc":{"id":"instrumentos/tdc","title":"Transfere\u0302ncia do Direito de Construir (TDC)","description":"A Transfer\xeancia do Direito de Construir (TDC) \xe9 o instrumento de pol\xedtica urbana pelo qual \xe9 poss\xedvel que um propriet\xe1rio de im\xf3vel com relev\xe2ncia de preserva\xe7\xe3o natural ou considerado um bem cultural aliene a um outro empreendedor ou utilize em outro lugar o potencial construtivo de que teria direito pelo zoneamento no imovel protegido. Outras utiliza\xe7\xf5es do instrumento s\xe3o para viabiliza\xe7\xe3o de equipamentos p\xfablicos e de infraestrutura vi\xe1ria. Empregado desde 1996, a ferramenta ganhou maior amplitude e facilidade de utiliza\xe7\xe3o com a aprova\xe7\xe3o do novo Plano Diretor, Lei n\xba 11.181, de 2019.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Monitoramento da Pol\xedtica Urbana","description":"O Monitoramento da Pol\xedtica Urbana tem como objetivo acompanhar como a produ\xe7\xe3o do espa\xe7o urbano est\xe1 respondendo \xe0 orienta\xe7\xe3o da legisla\xe7\xe3o urban\xedstica e de seus programas e projetos, sobretudo a partir da aplica\xe7\xe3o da Lei 11.181 de 2019 - Plano Diretor Municipal. O Plano Diretor define como responsabilidade do Executivo o monitoramento, por meio de indicadores, para avalia\xe7\xe3o peri\xf3dica da pol\xedtica urbana baseada nas premissas da Nova Agenda Urbana (NAU) e do Objetivo do Desenvolvimento Sustent\xe1vel 11 (ODS 11).*","sidebar":"tutorialSidebar"},"metodologia/informacoes":{"id":"metodologia/informacoes","title":"Informa\xe7\xf5es importantes","description":"Os pain\xe9is s\xe3o atualizados de acordo com a disponibilidade e sistematiza\xe7\xe3o dos dados. O Boletim \xe9 divulgado periodicamente a cada 6 meses com o monitoramento dos indicadores apresentados no Painel de Indicadores.","sidebar":"tutorialSidebar"},"metodologia/introducao":{"id":"metodologia/introducao","title":"Introdu\xe7\xe3o","description":"O objetivo do monitoramento \xe9 acompanhar como o ordenamento urbano est\xe1 respondendo a orienta\xe7\xe3o da legisla\xe7\xe3o urban\xedstica, programas e projetos, sobretudo, aos vinculados \xe0s premissas da Nova Agenda Urbana (NAU)*. O monitoramento permite: I. a leitura temporal da transforma\xe7\xe3o urbana; II. acompanhar a ader\xeancia dos par\xe2metros urban\xedsticos na ocupa\xe7\xe3o e uso e do territ\xf3rio; III. acompanhar os resultados do est\xedmulo para a transforma\xe7\xe3o de uma determinada \xe1rea ou de uma caracter\xedstica urbana; dentre outras possibilidades.","sidebar":"tutorialSidebar"}}}}')}}]);